-- Dialmade: accounts (Better Auth) and «Mis diseños».
--
-- Additive and idempotent: only `create … if not exists`, `create or replace` and grants. Nothing existing
-- is altered or dropped. Apply it after 20261010120000_ai_ledger.sql. That one was applied by hand: run
-- `supabase migration repair --status applied 20261010120000` before any `supabase db push`.
--
-- Better Auth's tables live in their own schema `dialmade_auth` (Better Auth's `database.schemaName`),
-- generated by Better Auth 1.7.7's own migration planner and reviewed by hand. The app's tables live in the
-- private schema `dialmade`. Neither schema is exposed by the Data API, RLS is on everywhere and there are
-- no policies: anon / authenticated (publishable key) cannot read or write anything. Only the web server
-- reaches them, through DATABASE_URL, and it checks the signed-in user on every query
-- (apps/web/src/lib/designs/repository.ts): there is no Supabase Auth, so no auth.uid() for RLS.
--
-- Personal data: email, name and avatar URL of accounts; IP and user agent of sessions (Better Auth's
-- session list). Anonymous devices get a placeholder email. Emails in the rate limit table are HMACs.
-- OAuth tokens are stored encrypted (Better Auth's account.encryptOAuthTokens).

create schema if not exists dialmade_auth;
revoke all on schema dialmade_auth from public;
revoke all on schema dialmade_auth from anon, authenticated;

-- ---- Better Auth core ----------------------------------------------------------------------------------

create table if not exists dialmade_auth."user" (
  "id" text not null primary key,
  "name" text not null,
  "email" text not null unique,
  "emailVerified" boolean not null,
  "image" text,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz default CURRENT_TIMESTAMP not null,
  -- anonymous plugin: «Guardar en este dispositivo sin cuenta».
  "isAnonymous" boolean
);

create table if not exists dialmade_auth."session" (
  "id" text not null primary key,
  "expiresAt" timestamptz not null,
  "token" text not null unique,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz not null,
  "ipAddress" text,
  "userAgent" text,
  "userId" text not null references dialmade_auth."user" ("id") on delete cascade
);

-- OAuth accounts (GitHub, Google). "password" stays null: there is no email + password sign-in.
create table if not exists dialmade_auth."account" (
  "id" text not null primary key,
  "accountId" text not null,
  "providerId" text not null,
  "userId" text not null references dialmade_auth."user" ("id") on delete cascade,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  "scope" text,
  "password" text,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz not null
);

-- Magic link tokens (stored hashed) and OAuth state.
create table if not exists dialmade_auth."verification" (
  "id" text not null primary key,
  "identifier" text not null,
  "value" text not null,
  "expiresAt" timestamptz not null,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz default CURRENT_TIMESTAMP not null
);

-- passkey plugin.
create table if not exists dialmade_auth."passkey" (
  "id" text not null primary key,
  "name" text,
  "publicKey" text not null,
  "userId" text not null references dialmade_auth."user" ("id") on delete cascade,
  "credentialID" text not null,
  "counter" integer not null,
  "deviceType" text not null,
  "backedUp" boolean not null,
  "transports" text,
  "createdAt" timestamptz,
  "aaguid" text
);

-- Rate limit counters (rateLimit.storage = "database"): shared by every serverless instance. The key is the
-- client IP (IPv6 grouped by /64) and the path.
create table if not exists dialmade_auth."rateLimit" (
  "id" text not null primary key,
  "key" text not null unique,
  "count" integer not null,
  "lastRequest" bigint not null
);

create index if not exists "session_userId_idx" on dialmade_auth."session" ("userId");
create index if not exists "account_userId_idx" on dialmade_auth."account" ("userId");
create index if not exists "verification_identifier_idx" on dialmade_auth."verification" ("identifier");
create index if not exists "passkey_userId_idx" on dialmade_auth."passkey" ("userId");
create index if not exists "passkey_credentialID_idx" on dialmade_auth."passkey" ("credentialID");
create index if not exists "user_anonymous_updated_idx" on dialmade_auth."user" ("updatedAt") where "isAnonymous";

-- ---- Dialmade ---------------------------------------------------------------------------------------------

create schema if not exists dialmade;
revoke all on schema dialmade from public;
revoke all on schema dialmade from anon, authenticated;

-- «Mis diseños»: one DesignDoc (v2, validated by the server) per row. Deleting the user deletes them.
create table if not exists dialmade.designs (
  id uuid primary key default gen_random_uuid(),
  user_id text not null references dialmade_auth."user" ("id") on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  doc jsonb not null,
  doc_version integer not null check (doc_version >= 1),
  preview jsonb not null default '{}'::jsonb,
  size_bytes integer not null check (size_bytes between 0 and 2000000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table dialmade.designs is 'Saved DesignDocs of «Mis diseños». Every query filters by user_id in the server (no RLS policies).';

create index if not exists designs_user_updated_idx on dialmade.designs (user_id, updated_at desc);

-- Fixed-window counters of the server's own limits: magic links per email address (as an HMAC, never the
-- address) and per day overall, and writes to «Mis diseños» per user. Rows older than two days are deleted by
-- the server.
create table if not exists dialmade.rate_limits (
  key text not null check (char_length(key) between 1 and 200),
  window_start timestamptz not null,
  hits integer not null default 0 check (hits >= 0),
  primary key (key, window_start)
);

create index if not exists rate_limits_window_idx on dialmade.rate_limits (window_start);

-- ---- Housekeeping -----------------------------------------------------------------------------------------

-- Anonymous devices that never signed in (and their designs, by cascade) after `p_days` without activity,
-- expired sessions and verifications, and old rate limit counters. Not scheduled yet: see
-- docs/design/login-pendientes.md (pg_cron, free on Supabase). Returns the anonymous users deleted.
create or replace function dialmade_auth.purge_stale(p_days integer default 30)
returns integer
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_count integer;
begin
  if p_days is null or p_days < 7 then
    raise exception 'p_days must be >= 7' using errcode = '22023';
  end if;

  with stale as (
    delete from dialmade_auth."user" u
     where u."isAnonymous"
       and u."updatedAt" < now() - make_interval(days => p_days)
       and not exists (
         select 1 from dialmade_auth."session" s
          where s."userId" = u."id" and s."updatedAt" >= now() - make_interval(days => p_days)
       )
    returning 1
  )
  select count(*)::integer into v_count from stale;

  delete from dialmade_auth."session" where "expiresAt" < now();
  delete from dialmade_auth."verification" where "expiresAt" < now() - interval '1 day';
  delete from dialmade_auth."rateLimit" where "lastRequest" < (extract(epoch from now()) * 1000)::bigint - 86400000;
  delete from dialmade.rate_limits where window_start < now() - interval '2 days';

  return v_count;
end;
$$;
revoke all on function dialmade_auth.purge_stale(integer) from public, anon, authenticated;

-- ---- Lock down --------------------------------------------------------------------------------------------

alter table dialmade_auth."user" enable row level security;
alter table dialmade_auth."session" enable row level security;
alter table dialmade_auth."account" enable row level security;
alter table dialmade_auth."verification" enable row level security;
alter table dialmade_auth."passkey" enable row level security;
alter table dialmade_auth."rateLimit" enable row level security;
alter table dialmade.designs enable row level security;
alter table dialmade.rate_limits enable row level security;

revoke all on all tables in schema dialmade_auth from public;
revoke all on all tables in schema dialmade_auth from anon, authenticated;
revoke all on all tables in schema dialmade from public;
revoke all on all tables in schema dialmade from anon, authenticated;
